from gramcommon import *
# 중1 천재(소영순) 4·5·6과 문법 (11/1) — 선생님 요청: 난이도 상·중 문제 위주, 개념은 아주 간단히
# 4과: 과거시제 · 동명사 / 5과: 비교급 · 최상급 / 6과: to부정사 부사적 용법 · 접속사 that
# 근거: Grammar Build Up 객관식 4·5·6과 유형(똑같이 말고 살짝 바꿔서) + 교과서 본문 문장
# 위치: 각 과 본문 뒤 (4과 → L4b 뒤, 5과 → L5b 뒤, 6과 → d2 뒤)

G = {4: [], 5: [], 6: []}
PG = '어법상 알맞은 것을 고르세요.'

def day(did, rng, story, notes, pick, use, real, err, scr):
    D = Day(did, rng, story)
    D.note('핵심 개념', notes)
    D.step(PICK(D, '어법 선택', pick))
    D.step(MC('쓰임 구별 · 의미', use))
    D.step(MC('실전 어법 (상·중)', real))
    D.step(ERR(D, '오류 찾기', err))
    D.step(SCR(D, '우리말 → 영어 배열', scr))
    return D.done()

