for k in G:
    for d in G[k]: ansfirst(d['steps'])
path = sys.argv[1] if len(sys.argv) > 1 else '/home/claude/proj/data/m1-chunjae-so-L6.js'
PK = json.loads(subprocess.check_output(['node', '-e', "global.window={};require('%s');process.stdout.write(JSON.stringify(window.PKG))" % path]))
base = [d for d in PK['days'] if not re.match(r'q\d[ab]$', d['id'])]
out = []
for d in base:
    out.append(d)
    if d['id'] == 'L4b': out += G[4]
    if d['id'] == 'L5b': out += G[5]
    if d['id'] == 'd2': out += G[6]
assert len(out) == len(base) + 6
PK['days'] = out
for i, d in enumerate(PK['days']): d['name'] = 'DAY %d' % (i + 1)
src = open(path, encoding='utf-8').read(); head = src[:src.index('window.PKG')]
if '4·5·6과 문법' not in head: head = head.rstrip('\n') + '\n/* 11/1: 4·5·6과 문법 각 과 본문 뒤에 추가(과거시제·동명사 / 비교급·최상급 / to부정사 부사적·접속사 that) (gen/gen_m1c46gram.py) */\n'
write(PK, path, head)
print('ok', [(d['name'], d['id'], d['range'], len(d['steps'])) for d in PK['days']])
